from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return {"ok": False, "error": "missing field"}
    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return {"ok": False, "error": "bad grid"}
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return {"ok": False, "error": "bad width"}
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return {"ok": False, "error": "bad height"}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": "bad cell size"}
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}
    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    sums = {}
    counts = {}
    degraded = set()
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        if not isinstance(obs, dict):
            return {"ok": False, "error": "bad observation"}
        if "x" not in obs or not isinstance(obs["x"], int):
            return {"ok": False, "error": "bad observation"}
        if "y" not in obs or not isinstance(obs["y"], int):
            return {"ok": False, "error": "bad observation"}
        if "value" not in obs or not isinstance(obs["value"], int):
            return {"ok": False, "error": "bad observation"}
        if "quality" not in obs or not isinstance(obs["quality"], int):
            return {"ok": False, "error": "bad observation"}
        if obs["quality"] < 0 or obs["quality"] > 100:
            return {"ok": False, "error": "bad observation"}

        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue

        x = obs["x"]
        if x < 0:
            dropped = dropped + 1
            continue
        col = x // cell_size
        if col >= width:
            if x - width * cell_size < tolerance:
                col = width - 1
            else:
                dropped = dropped + 1
                continue

        y = obs["y"]
        if y < 0:
            dropped = dropped + 1
            continue
        row = y // cell_size
        if row >= height:
            if y - height * cell_size < tolerance:
                row = height - 1
            else:
                dropped = dropped + 1
                continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded.add(key)

    fill_value = raw["fill_value"]
    cells = _averaged_rows(sums, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    return [
        [sums[(r, c)] // counts[(r, c)] if (r, c) in counts else fill_value
         for c in range(width)]
        for r in range(height)
    ]


def _flag_rows(counts: dict, degraded: set, width: int, height: int) -> list:
    return [
        ["empty" if (r, c) not in counts else "degraded" if (r, c) in degraded else "good"
         for c in range(width)]
        for r in range(height)
    ]


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return f"cells={total_cells};filled={filled};dropped={dropped};rejected={rejected};saturated={saturated};coverage={coverage}"

from __future__ import annotations

from collections import defaultdict

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

_ERROR_MAP: dict[type, str] = {
    dict: "malformed input",
    KeyError: "missing field",
    ValueError: "bad grid",
}

_MISSING_KEYS = ("grid", "observations", "fill_value")
_OBS_FIELDS = ("x", "y", "value", "quality")

_GRID_CHECKS: list[tuple[str, int, int | None]] = [
    ("width", 1, MAX_DIM),
    ("height", 1, MAX_DIM),
    ("cell_size", 1, None),
]


def _valid_dict(raw: object) -> str | None:
    if not isinstance(raw, dict):
        return _ERROR_MAP[dict]
    return None


def _valid_fields(raw: dict) -> str | None:
    for key in _MISSING_KEYS:
        if key not in raw:
            return _ERROR_MAP[KeyError]
    return None


def _valid_grid(grid: dict) -> tuple[str | None, int, int, int]:
    for key in ("width", "height", "cell_size"):
        if key not in grid:
            return _ERROR_MAP[ValueError], 0, 0, 0

    width, height, cell_size = grid["width"], grid["height"], grid["cell_size"]
    for name, lo, hi in _GRID_CHECKS:
        val = grid[name]
        if not isinstance(val, int) or val < lo or (hi is not None and val > hi):
            return _ERROR_MAP[ValueError], 0, 0, 0
    return None, width, height, cell_size


def _valid_fill_value(fv: object) -> str | None:
    if not isinstance(fv, int):
        return _ERROR_MAP[ValueError]
    return None


def _valid_observations(observations: object) -> str | None:
    if not isinstance(observations, list):
        return _ERROR_MAP[ValueError]
    return None


def _valid_obs(obs: object) -> str | None:
    if not isinstance(obs, dict):
        return _ERROR_MAP[ValueError]
    for f in _OBS_FIELDS:
        if f not in obs or not isinstance(obs[f], int):
            return _ERROR_MAP[ValueError]
    if not (0 <= obs["quality"] <= 100):
        return _ERROR_MAP[ValueError]
    return None


def _averaged_rows(sums: defaultdict, counts: defaultdict, width: int, height: int, fill_value: int) -> list:
    return [
        [sums[(r, c)] // counts[(r, c)] if (r, c) in counts else fill_value
         for c in range(width)]
        for r in range(height)
    ]


def _flag_rows(counts: defaultdict, degraded: set, width: int, height: int) -> list:
    return [
        ["empty" if (r, c) not in counts else "degraded" if (r, c) in degraded else "good"
         for c in range(width)]
        for r in range(height)
    ]


def _coverage(counts: defaultdict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return ";".join(f"{k}={v}" for k, v in (
        ("cells", total_cells), ("filled", filled), ("dropped", dropped),
        ("rejected", rejected), ("saturated", saturated), ("coverage", coverage),
    ))


def accumulate_grid(raw: object) -> dict:
    err = _valid_dict(raw)
    if err:
        return {"ok": False, "error": err}

    err = _valid_fields(raw)
    if err:
        return {"ok": False, "error": err}

    grid = raw["grid"]
    result = _valid_grid(grid)
    if isinstance(result[0], str):
        return {"ok": False, "error": result[0]}
    _, width, height, cell_size = result

    err = _valid_fill_value(raw["fill_value"])
    if err:
        return {"ok": False, "error": err}

    err = _valid_observations(raw["observations"])
    if err:
        return {"ok": False, "error": err}

    sums: defaultdict = defaultdict(int)
    counts: defaultdict = defaultdict(int)
    degraded: set = set()
    dropped = rejected = saturated = 0
    tolerance = cell_size // 2

    for obs in raw["observations"]:
        err = _valid_obs(obs)
        if err:
            return {"ok": False, "error": err}

        if obs["quality"] < MIN_QUALITY:
            rejected += 1
            continue

        x = obs["x"]
        if x < 0:
            dropped += 1
            continue
        col = x // cell_size
        if col >= width:
            if x - width * cell_size < tolerance:
                col = width - 1
            else:
                dropped += 1
                continue

        y = obs["y"]
        if y < 0:
            dropped += 1
            continue
        row = y // cell_size
        if row >= height:
            if y - height * cell_size < tolerance:
                row = height - 1
            else:
                dropped += 1
                continue

        key = (row, col)
        if key in counts and counts[key] >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] += obs["value"]
        counts[key] += 1
        if obs["quality"] < GOOD_QUALITY:
            degraded.add(key)

    cells = _averaged_rows(sums, counts, width, height, raw["fill_value"])
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)

    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }

