    else:
        fee += REINSTATE_SURCHARGE
        status = "reinstated"
    receipt = f"{payment['method']}:{member['id']}:{status}:{fee}"
    return {"ok": True, "status": status, "fee": fee, "receipt": receipt}


def _compute_suspended(member: dict, payment: dict) -> dict:
    if "strikes" not in member or not isinstance(member["strikes"], int) or member["strikes"] < 0:
        return {"ok": False, "error": "bad strikes"}
    if member["strikes"] >= MAX_STRIKES:
        return {"ok": False, "error": "too many strikes"}
    fee = TIER_FEES[member["tier"]]
    fee += fee // 2
    status = "reactivated"
    receipt = f"{payment['method']}:{member['id']}:{status}:{fee}"
    return {"ok": True, "status": status, "fee": fee, "receipt": receipt}


_HANDLERS: dict[str, Any] = {
    "active": _compute_active,
    "lapsed": _compute_lapsed,
    "suspended": _compute_suspended,
}


def process_renewal(raw_member: Any, raw_payment: Any) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return {"ok": False, "error": "malformed input"}

    err = _check_common(raw_member, raw_payment)
    if err is not None:
        return err

    if raw_member["status"] == "banned":
        return {"ok": False, "error": "member banned"}

    handler = _HANDLERS.get(raw_member["status"])
    if handler is None:
        return {"ok": False, "error": "unknown status"}

    result = handler(raw_member, raw_payment)
    if not result["ok"]:
        return result

    if raw_payment["amount"] < result["fee"]:
        return {"ok": False, "error": "insufficient payment"}

    return result

