def qc_series(raw: object) -> dict:
    error = _validate_input(raw)
    if error is not None:
        return {"ok": False, "error": error}
    values = raw["values"]
    timestamps = raw["timestamps"]
    gaps = _count_gaps(timestamps, raw["expected_step"])
    deviations = _deviations(values)
    labels, total, worst = classify_spikes(deviations, raw["hard_limit"])
    return {
        "ok": True,
        "labels": labels,
        "gaps": gaps,
        "score": total,
        "verdict": _verdict(total),
        "counts": _label_counts(labels),
        "trend": _trend(values),
        "streak": _longest_run(labels),
        "line": _summary_line(len(values), gaps, worst, total),
    }


def _validate_input(raw: object) -> str | None:
    if not isinstance(raw, dict):
        return "malformed input"
    if not all(k in raw for k in REQUIRED_FIELDS):
        return "missing field"
    series_error = _series_error(raw["values"], raw["timestamps"])
    if series_error is not None:
        return series_error
    return _bounds_error(raw["expected_step"], raw["hard_limit"])


def _series_error(values: object, timestamps: object) -> str | None:
    if not isinstance(values, list) or not values:
        return "bad values"
    if not isinstance(timestamps, list) or len(timestamps) != len(values):
        return "bad timestamps"
    if not all(isinstance(v, int) and isinstance(t, int) for v, t in zip(values, timestamps)):
        return "bad sample"
    return _order_error(timestamps)


def _order_error(timestamps: list[int]) -> str | None:
    if any(t <= prev for prev, t in zip(timestamps, timestamps[1:])):
        return "unordered timestamps"
    return None


def _bounds_error(expected_step: object, hard_limit: object) -> str | None:
    if not isinstance(expected_step, int) or expected_step <= 0:
        return "bad step"
    if not isinstance(hard_limit, int) or hard_limit <= 0:
        return "bad limit"
    return None


def _count_gaps(timestamps: list[int], expected_step: int) -> int:
    return sum(1 for a, b in zip(timestamps, timestamps[1:]) if b - a > expected_step)


def _deviations(values: list[int]) -> list[int]:
    return [abs(v - _window_median(values, i)) for i, v in enumerate(values)]


def _window_median(values: list[int], index: int) -> int:
    prev = values[index - 1] if index > 0 else values[index]
    nxt = values[index + 1] if index + 1 < len(values) else values[index]
    return _median3(prev, values[index], nxt)


def _median3(a: int, b: int, c: int) -> int:
    if a > b:
        a, b = b, a
    if b > c:
        b, c = c, b
    if a > b:
        a, b = b, a
    return b


def classify_spikes(deviations: list[int], hard_limit: int) -> tuple[list[str], int, int]:
    labels: list[str] = []
    total = 0
    worst = 0
    for d in deviations:
        label, score = _classify(d, hard_limit)
        labels.append(label)
        total += score
        if score > worst:
            worst = score
    return labels, total, worst


# Shared threshold logic — used by both classify_spikes and _worst_label.
_SPIKE_LEVELS = [(100, 12), (25, 6), (10, 3)]
_SPIKE_LABELS = {100: "invalid", 25: "severe", 10: "moderate", 3: "minor"}


def _classify(deviation: int, hard_limit: int) -> tuple[str, int]:
    if deviation >= hard_limit:
        return "invalid", 100
    for score, threshold in _SPIKE_LEVELS:
        if deviation >= threshold:
            return _SPIKE_LABELS[score], score
    return "clean", 0


def _worst_label(worst_score: int) -> str:
    for score in reversed(list(_SPIKE_LABELS)):
        if worst_score >= score:
            return _SPIKE_LABELS[score]
    return "clean"


def _label_counts(labels: list[str]) -> dict[str, int]:
    counts: dict[str, int] = {"clean": 0, "minor": 0, "moderate": 0, "severe": 0, "invalid": 0}
    for label in labels:
        counts[label] += 1
    return counts


def _trend(values: list[int]) -> str:
    delta = values[-1] - values[0]
    if delta > TREND_TOLERANCE:
        return "rising"
    if delta < -TREND_TOLERANCE:
        return "falling"
    return "stable"


def _longest_run(labels: list[str]) -> int:
    longest = 0
    current = 0
    for label in labels:
        if label == "clean":
            current = 0
        else:
            current += 1
            if current > longest:
