export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

const VIP_BENEFIT_THRESHOLD = 3;

function appliesVIPBenefit(loyaltyYears: number, coupon: unknown): boolean {
  return loyaltyYears >= VIP_BENEFIT_THRESHOLD || coupon === "VIP";
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  const loyaltyYears = req.loyaltyYears;
  if (!Number.isInteger(loyaltyYears) || loyaltyYears < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  if (req.category === "standard") {
    const nights = req.nights;
    const guests = req.guests;
    const season = req.season;
    const coupon = req.coupon;

    if (!Number.isInteger(nights) || nights < 1 || nights > 14) return { ok: false, error: "bad nights" };
    if (!Number.isInteger(guests) || guests < 1 || guests > 2) return { ok: false, error: "bad guests" };
    if (season !== "low" && season !== "high") return { ok: false, error: "bad season" };

    let total = 80 * nights;
    if (season === "high") total += 30 * nights;
    if (appliesVIPBenefit(loyaltyYears, coupon)) total -= Math.floor(total / 10);
    const policy = appliesVIPBenefit(loyaltyYears, coupon) ? "flex" : "strict";
    const line = `standard:${nights}n:${total}:${policy}`;
    return { ok: true, total, policy, line };
  }

  if (req.category === "suite") {
    const nights = req.nights;
    const guests = req.guests;
    const season = req.season;
    const coupon = req.coupon;

    if (!Number.isInteger(nights) || nights < 1 || nights > 21) return { ok: false, error: "bad nights" };
    if (!Number.isInteger(guests) || guests < 1 || guests > 4) return { ok: false, error: "bad guests" };
    if (season !== "low" && season !== "high") return { ok: false, error: "bad season" };

    let total = 150 * nights;
    if (season === "high") total += 60 * nights;
    if (appliesVIPBenefit(loyaltyYears, coupon)) total -= Math.floor(total / 10);
    if (guests > 2) total += 25;
    const policy = appliesVIPBenefit(loyaltyYears, coupon) ? "flex" : "strict";
    const line = `suite:${nights}n:${total}:${policy}`;
    return { ok: true, total, policy, line };
  }

  if (req.category === "villa") {
    const nights = req.nights;
    const guests = req.guests;
    const season = req.season;
    const coupon = req.coupon;

    if (!Number.isInteger(nights) || nights < 1 || nights > 28) return { ok: false, error: "bad nights" };
    if (nights < 3) return { ok: false, error: "villa minimum stay" };
    if (!Number.isInteger(guests) || guests < 1 || guests > 8) return { ok: false, error: "bad guests" };
    if (season !== "low" && season !== "high") return { ok: false, error: "bad season" };

    let total = 300 * nights;
    if (season === "high") total += 120 * nights;
    if (appliesVIPBenefit(loyaltyYears, coupon)) total -= Math.floor(total / 10);
    total += 500;
    const policy = appliesVIPBenefit(loyaltyYears, coupon) ? "flex" : "strict";
    const line = `villa:${nights}n:${total}:${policy}`;
    return { ok: true, total, policy, line };
  }

  return { ok: false, error: "unknown category" };
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

function field<T>(obj: Record<string, unknown>, name: string): T | undefined {
  return obj[name] as T | undefined;
}

function validateInt(
  obj: Record<string, unknown>,
  name: string,
  min: number,
  max: number
): number | string {
  const val = field<number>(obj, name);
  if (val === undefined || !Number.isInteger(val) || val < min || val > max) {
    return "bad " + name;
  }
  return val;
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  const loyalty = validateInt(req, "loyaltyYears", 0, Infinity);
  if (typeof loyalty === "string") {
    return { ok: false, error: "bad loyalty" };
  }

  if (req.category === "standard") {
    const nights = validateInt(req, "nights", 1, 14);
    if (typeof nights === "string") {
      return { ok: false, error: nights };
    }
    const guests = validateInt(req, "guests", 1, 2);
    if (typeof guests === "string") {
      return { ok: false, error: guests };
    }
    const season = field<string>(req, "season");
    if (season !== "low" && season !== "high") {
      return { ok: false, error: "bad season" };
    }

    let total = 80 * nights;
    if (season === "high") {
      total += 30 * nights;
    }
    if (loyalty >= 3 || field<string>(req, "coupon") === "VIP") {
      total -= Math.floor(total / 10);
    }
    const policy = field<string>(req, "coupon") === "VIP" || loyalty > 2 ? "flex" : "strict";
    const line = "standard:" + nights + "n:" + total + ":" + policy;
    return { ok: true, total, policy, line };
  }

  if (req.category === "suite") {
    const nights = validateInt(req, "nights", 1, 21);
    if (typeof nights === "string") {
      return { ok: false, error: nights };
    }
    const guests = validateInt(req, "guests", 1, 4);
    if (typeof guests === "string") {
      return { ok: false, error: guests };
    }
    const season = field<string>(req, "season");
    if (season !== "low" && season !== "high") {
      return { ok: false, error: "bad season" };
    }

    let total = 150 * nights;
    if (season === "high") {
      total += 60 * nights;
    }
    if (field<string>(req, "coupon") === "VIP" || loyalty >= 3) {
      total -= Math.floor(total / 10);
    }
    if (guests > 2) {
      total += 25;
    }
    const policy = field<string>(req, "coupon") === "VIP" || loyalty >= 3 ? "flex" : "strict";
    const line = "suite:" + nights + "n:" + total + ":" + policy;
    return { ok: true, total, policy, line };
  }

  if (req.category === "villa") {
    const nights = validateInt(req, "nights", 1, 28);
    if (typeof nights === "string") {
      return { ok: false, error: nights };
    }
    if (nights < 3) {
      return { ok: false, error: "villa minimum stay" };
    }
    const guests = validateInt(req, "guests", 1, 8);
    if (typeof guests === "string") {
      return { ok: false, error: guests };
    }
    const season = field<string>(req, "season");
    if (season !== "low" && season !== "high") {
      return { ok: false, error: "bad season" };
    }

    let total = 300 * nights;
    if (season === "high") {
      total += 120 * nights;
    }
    if (loyalty > 2 || field<string>(req, "coupon") === "VIP") {
      total -= Math.floor(total / 10);
    }
    total += 500;
    const policy = field<string>(req, "coupon") === "VIP" || loyalty >= 3 ? "flex" : "strict";
    const line = "villa:" + nights + "n:" + total + ":" + policy;
    return { ok: true, total, policy, line };
  }

  return { ok: false, error: "unknown category" };
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryConfig {
  category: string;
  minNights: number;
  maxNights: number;
  minGuests: number;
  maxGuests: number;
  baseRate: number;
  highRate: number;
  minDiscountYears: number;
  extraGuestThreshold: number;
  extraGuestFee: number;
  flatFee: number;
  linePrefix: string;
  nightMinCheck?: (nights: number) => string | null;
}

const CATEGORIES: Record<string, CategoryConfig> = {
  standard: {
    category: "standard",
    minNights: 1, maxNights: 14,
    minGuests: 1, maxGuests: 2,
    baseRate: 80, highRate: 30,
    minDiscountYears: 3,
    extraGuestThreshold: 2, extraGuestFee: 0,
    flatFee: 0,
    linePrefix: "standard",
  },
  suite: {
    category: "suite",
    minNights: 1, maxNights: 21,
    minGuests: 1, maxGuests: 4,
    baseRate: 150, highRate: 60,
    minDiscountYears: 3,
    extraGuestThreshold: 2, extraGuestFee: 25,
    flatFee: 0,
    linePrefix: "suite",
  },
  villa: {
    category: "villa",
    minNights: 1, maxNights: 28,
    minGuests: 1, maxGuests: 8,
    baseRate: 300, highRate: 120,
    minDiscountYears: 3,
    extraGuestThreshold: 0, extraGuestFee: 0,
    flatFee: 500,
    linePrefix: "villa",
    nightMinCheck: (nights: number) => (nights < 3 ? "villa minimum stay" : null),
  },
};

function isValidSeason(season: unknown): boolean {
  return season === "low" || season === "high";
}

function isFlexPolicy(coupon: unknown, loyaltyYears: number): boolean {
  return coupon === "VIP" || loyaltyYears >= 3;
}

function calcTotal(config: CategoryConfig, nights: number, season: string, loyaltyYears: number, coupon: unknown, guests: number): number {
  let total = config.baseRate * nights;
  if (season === "high") {
    total += config.highRate * nights;
  }
  if (coupon === "VIP" || loyaltyYears >= config.minDiscountYears) {
    total -= Math.floor(total / 10);
  }
  if (guests > config.extraGuestThreshold) {
    total += config.extraGuestFee;
  }
  total += config.flatFee;
  return total;
}

function validateRequest(req: Record<string, unknown>): { ok: false; error: string } | { nights: number; guests: number; season: string; loyaltyYears: number } {
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }
  const loyaltyYears = req.loyaltyYears as number;

  const category = req.category;
  if (typeof category !== "string" || !(category in CATEGORIES)) {
    return { ok: false, error: "unknown category" };
  }
  const config = CATEGORIES[category];

  if (!Number.isInteger(req.nights)) {
    return { ok: false, error: "bad nights" };
  }
  const nights = req.nights as number;
  if (nights < config.minNights || nights > config.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  const nightErr = config.nightMinCheck?.(nights);
  if (nightErr) {
    return { ok: false, error: nightErr };
  }

  if (!Number.isInteger(req.guests) || (req.guests as number) < config.minGuests || (req.guests as number) > config.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  const guests = req.guests as number;

  if (!isValidSeason(req.season)) {
    return { ok: false, error: "bad season" };
  }
  const season = req.season as string;

  return { ok: true, nights, guests, season, loyaltyYears };
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  const validated = validateRequest(req);
  if (!validated.ok) {
    return { ok: false, error: validated.error };
  }

  const { nights, guests, season, loyaltyYears } = validated;
  const config = CATEGORIES[req.category as string];
  const total = calcTotal(config, nights, season, loyaltyYears, req.coupon, guests);
  const policy = isFlexPolicy(req.coupon, loyaltyYears) ? "flex" : "strict";
  const line = `${config.linePrefix}:${nights}n:${total}:${policy}`;

  return { ok: true, total, policy, line };
}

