  maxNights: number;
  maxGuests: number;
  baseRate: number;
  highRate: number;
  extraGuestFee: number;
  discountYears: number;
  flexYears: number;
  extraFee: number;
}

const CATEGORIES: Record<string, CategorySpec> = {
  standard: {
    name: "standard", minNights: 1, maxNights: 14, maxGuests: 2,
    baseRate: 80, highRate: 30, extraGuestFee: 25,
    discountYears: 3, flexYears: 2, extraFee: 0,
  },
  suite: {
    name: "suite", minNights: 1, maxNights: 21, maxGuests: 4,
    baseRate: 150, highRate: 60, extraGuestFee: 25,
    discountYears: 3, flexYears: 2, extraFee: 0,
  },
  villa: {
    name: "villa", minNights: 3, maxNights: 28, maxGuests: 8,
    baseRate: 300, highRate: 120, extraGuestFee: 25,
    discountYears: 3, flexYears: 2, extraFee: 500,
  },
};

interface ValidationResult {
  nights?: number;
  guests?: number;
  error?: string;
  spec?: CategorySpec;
}

function validateLoyalty(req: Record<string, unknown>): ValidationResult | null {
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { error: "bad loyalty" };
  }
  return null;
}

function resolveCategory(req: Record<string, unknown>): ValidationResult | null {
  const spec = CATEGORIES[req.category as string];
  if (!spec) return { error: "unknown category" };
  return { spec };
}

function validateNights(spec: CategorySpec, req: Record<string, unknown>): ValidationResult | null {
  const nights = req.nights as number;
  if (!Number.isInteger(nights) || nights < spec.minNights || nights > spec.maxNights) {
    return { error: "bad nights" };
  }
  return null;
}

function validateGuests(spec: CategorySpec, req: Record<string, unknown>): ValidationResult | null {
  const guests = req.guests as number;
  if (!Number.isInteger(guests) || guests < 1 || guests > spec.maxGuests) {
    return { error: "bad guests" };
  }
  return null;
}

function validateSeason(req: Record<string, unknown>): ValidationResult | null {
  if (req.season !== "low" && req.season !== "high") {
    return { error: "bad season" };
  }
  return null;
}

function validate(req: Record<string, unknown>): ValidationResult {
  const e1 = validateLoyalty(req);
  if (e1) return e1;
  const catResult = resolveCategory(req);
  if (catResult.error) return catResult;
  const spec = catResult.spec!;
  const e2 = validateNights(spec, req);
  if (e2) return e2;
  const e3 = validateGuests(spec, req);
  if (e3) return e3;
  const e4 = validateSeason(req);
  if (e4) return e4;
  return { nights: req.nights as number, guests: req.guests as number };
}

function computeTotal(spec: CategorySpec, nights: number, guests: number, season: string, coupon: unknown, loyaltyYears: number): number {
  let total = spec.baseRate * nights;
  if (season === "high") total += spec.highRate * nights;
  if (loyaltyYears >= spec.discountYears || coupon === "VIP") total -= Math.floor(total / 10);
  if (guests > 2) total += spec.extraGuestFee;
  total += spec.extraFee;
  return total;
}

function computePolicy(coupon: unknown, loyaltyYears: number, flexYears: number): "strict" | "flex" {
  return loyaltyYears > flexYears || coupon === "VIP" ? "flex" : "strict";
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  const validation = validate(req);
  if (validation.error) return { ok: false, error: validation.error };

  const { nights, guests } = validation;
  const spec = CATEGORIES[req.category as string];
  const loyaltyYears = req.loyaltyYears as number;
  const total = computeTotal(spec, nights!, guests!, req.season as string, req.coupon, loyaltyYears);
  const policy = computePolicy(req.coupon, loyaltyYears, spec.flexYears);

  return { ok: true, total, policy, line: `${spec.name}:${nights}n:${total}:${policy}` };
}

files.process_events.ts:
interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

// ── Helpers ──

function strNonEmpty(v: unknown): v is string {
  return typeof v === "string" && v.length > 0;
}

function intPos(v: unknown): v is number {
  return Number.isInteger(v) && v >= 1;
}

function intNonNeg(v: unknown): v is number {
  return Number.isInteger(v) && v >= 0;
}

/** Exhaust the backorder queue, promoting eligible items to reserved. */
function drainQueue(
  queue: string[],
  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  stock: Record<string, number>,
  orders: Record<string, string>,
): void {
  for (let pos = 0; pos < queue.length; pos++) {
    const pendingId = queue[pos];
    const want = pendingWants[pendingId];
    const onHand = stock[want.item] ?? 0;
    if (onHand >= want.qty) {
      stock[want.item] = onHand - want.qty;
      reserved[pendingId] = { item: want.item, qty: want.qty };
      orders[pendingId] = "reserved";
      delete pendingWants[pendingId];
      queue.splice(pos, 1);
      pos--;
    }
  }
}

// ── Event types ──

interface OrderEvent {
  type: "order";
  id: string;
  item: string;
  qty: number;
}

interface CancelEvent {
  type: "cancel";
  id: string;
}

interface ShipEvent {
  type: "ship";
  id: string;
  qty?: number;
}

interface RestockEvent {
  type: "restock";
  item: string;
  qty: number;
}

interface ExpireEvent {
  type: "expire";
  id: string;
}

type Event = OrderEvent | CancelEvent | ShipEvent | RestockEvent | ExpireEvent;

function validateEvent(raw: Record<string, unknown>, index: number): Event | undefined {
  const type = raw.type;
  if (!strNonEmpty(type)) return undefined;

  switch (type) {
    case "order": {
      const id = raw.id;
      const item = raw.item;
      const qty = raw.qty;
      if (!strNonEmpty(id) || !strNonEmpty(item) || !intPos(qty)) return undefined;
      return { type: "order", id, item, qty };
    }
    case "cancel": {
      const id = raw.id;
      if (!strNonEmpty(id)) return undefined;
      return { type: "cancel", id };
    }
    case "ship": {
      const id = raw.id;
      const qty = raw.qty;
      if (!strNonEmpty(id)) return undefined;
      if (qty !== undefined && !intPos(qty)) return undefined;
      return { type: "ship", id, qty };
    }
    case "restock": {
      const item = raw.item;
      const qty = raw.qty;
      if (!strNonEmpty(item) || !intPos(qty)) return undefined;
      return { type: "restock", item, qty };
    }
    case "expire": {
      const id = raw.id;
      if (!strNonEmpty(id)) return undefined;
      return { type: "expire", id };
    }
    default:
      return undefined;
  }
}

function err(index: number, msg: string) {
  return { ok: false, error: `event ${index}: ${msg}` };
}

// ── Event handlers ──

function handleOrder(
  ev: OrderEvent,
  index: number,
  stock: Record<string, number>,
  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  queue: string[],
  orders: Record<string, string>,
): FulfillmentResult | undefined {
  if (orders[ev.id] !== undefined) return err(index, "duplicate order");
  const available = stock[ev.item] ?? 0;
  if (available >= ev.qty) {
    stock[ev.item] = available - ev.qty;
    reserved[ev.id] = { item: ev.item, qty: ev.qty };
    orders[ev.id] = "reserved";
  } else {
    queue.push(ev.id);
    pendingWants[ev.id] = { item: ev.item, qty: ev.qty };
    orders[ev.id] = "backordered";
  }
  return undefined;
}

function handleCancel(
  ev: CancelEvent,
  index: number,
  stock: Record<string, number>,
  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  queue: string[],
  orders: Record<string, string>,
  rejected: { value: number },
): FulfillmentResult | undefined {
  if (reserved[ev.id] !== undefined) {
    const holding = reserved[ev.id]!;
    const back = stock[holding.item] ?? 0;
    stock[holding.item] = back + holding.qty;
    delete reserved[ev.id];
    orders[ev.id] = "cancelled";
    drainQueue(queue, reserved, pendingWants, stock, orders);
  } else if (orders[ev.id] === "backordered") {
    const pos = queue.indexOf(ev.id);
    if (pos !== -1) queue.splice(pos, 1);
    delete pendingWants[ev.id];
    orders[ev.id] = "cancelled";
  } else {
    rejected.value++;
  }
  return undefined;
}

function handleShip(
  ev: ShipEvent,
  index: number,
  reserved: Record<string, Want>,
  orders: Record<string, string>,
  rejected: { value: number },
): FulfillmentResult | undefined {
  if (reserved[ev.id] === undefined) {
    rejected.value++;
  } else if (ev.qty === undefined || ev.qty === reserved[ev.id].qty) {
    delete reserved[ev.id];
    orders[ev.id] = "shipped";
  } else if (ev.qty < reserved[ev.id].qty) {
    reserved[ev.id]!.qty -= ev.qty;
    orders[ev.id] = "partial";
  } else {
    rejected.value++;
  }
  return undefined;
}

function handleRestock(
  ev: RestockEvent,
  index: number,
  stock: Record<string, number>,
  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  queue: string[],
  orders: Record<string, string>,
): FulfillmentResult | undefined {
  const held = stock[ev.item] ?? 0;
  stock[ev.item] = held + ev.qty;
  drainQueue(queue, reserved, pendingWants, stock, orders);
  return undefined;
}

function handleExpire(
  ev: ExpireEvent,
  index: number,
  stock: Record<string, number>,
  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  queue: string[],
  orders: Record<string, string>,
  rejected: { value: number },
): FulfillmentResult | undefined {
  if (reserved[ev.id] !== undefined) {
    const holding = reserved[ev.id]!;
    const back = stock[holding.item] ?? 0;
    stock[holding.item] = back + holding.qty;
    delete reserved[ev.id];
    orders[ev.id] = "expired";
    drainQueue(queue, reserved, pendingWants, stock, orders);
  } else {
    rejected.value++;
  }
  return undefined;
}

// ── Main ──

export function processEvents(raw: unknown): FulfillmentResult {
  // validate stock
  if (typeof raw !== "object" || raw === null) return { ok: false, error: "malformed input" };
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) return { ok: false, error: "bad stock" };

  const stock: Record<string, number> = {};
  for (const [item, val] of Object.entries(input.stock as Record<string, unknown>)) {
    if (!intNonNeg(val)) return { ok: false, error: "bad stock" };
    stock[item] = val as number;
  }
  if (!Array.isArray(input.events)) return { ok: false, error: "bad events" };

  const orders: Record<string, string> = {};
  const reserved: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  const rej = { value: 0 };

  for (let i = 0; i < input.events.length; i++) {
    const rawEvent = input.events[i];
    if (typeof rawEvent !== "object" || rawEvent === null) {
      return { ok: false, error: `event ${i}: malformed` };
    }

    const ev = validateEvent(rawEvent as Record<string, unknown>, i);
    if (ev === undefined) return { ok: false, error: `event ${i}: bad type` };

    let result: FulfillmentResult | undefined;
    switch (ev.type) {
      case "order":
        result = handleOrder(ev, i, stock, reserved, pendingWants, queue, orders);
        break;
      case "cancel":
        result = handleCancel(ev, i, stock, reserved, pendingWants, queue, orders, rej);
        break;
      case "ship":
        result = handleShip(ev, i, reserved, orders, rej);
        break;
      case "restock":
        result = handleRestock(ev, i, stock, reserved, pendingWants, queue, orders);
        break;
      case "expire":
        result = handleExpire(ev, i, stock, reserved, pendingWants, queue, orders, rej);
        break;
    }
    if (result !== undefined) return result;
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected: rej.value,
    report: buildReport(orders, rej.value),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) counts[status] = 0;
  for (const id of Object.keys(orders)) counts[orders[id]]++;
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = `orders=${Object.keys(orders).length}`;
  for (const status of STATUSES) line += `;${status}=${counts[status]}`;
  return `${line};rejected=${rejected}`;
}

