interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

function isNonNegInt(v: unknown): v is number {
  return typeof v === "number" && Number.isInteger(v) && v >= 0;
}

function isPosInt(v: unknown): v is number {
  return typeof v === "number" && Number.isInteger(v) && v >= 1;
}

function nonNullString(v: unknown): string | null {
  return typeof v === "string" && v.length > 0 ? v : null;
}

function advanceQueue(
  stock: Record<string, number>,
  queue: string[],
  pendingWants: Record<string, Want>,
  reserved: Record<string, Want>,
  orders: Record<string, string>,
): void {
  for (let i = 0; i < queue.length; i++) {
    const want = pendingWants[queue[i]];
    if (want === undefined) continue;
    const onHand = stock[want.item] ?? 0;
    if (onHand >= want.qty) {
      stock[want.item] = onHand - want.qty;
      reserved[queue[i]] = want;
      orders[queue[i]] = "reserved";
      delete pendingWants[queue[i]];
      queue.splice(i, 1);
      i--;
    }
  }
}

type EventHandler = (
  event: Record<string, unknown>,
  prefix: string,
  stock: Record<string, number>,
  orders: Record<string, string>,
  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  queue: string[],
  rejected: number,
) => number;

function handleOrder(
  _event: Record<string, unknown>,
  prefix: string,
  stock: Record<string, number>,
  orders: Record<string, string>,
  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  queue: string[],
  _rejected: number,
): number {
  const event = _event;
  const id = nonNullString(event.id);
  if (id === null) return -1;
  if (orders[id] !== undefined) return -1;
  const item = nonNullString(event.item);
  if (item === null) return -1;
  const qty = event.qty;
  if (!isPosInt(qty)) return -1;

  const available = stock[item] ?? 0;
  if (available >= qty) {
    stock[item] = available - qty;
    reserved[id] = { item, qty };
    orders[id] = "reserved";
  } else {
    queue.push(id);
    pendingWants[id] = { item, qty };
    orders[id] = "backordered";
  }
  return 0;
}

function handleCancel(
  event: Record<string, unknown>,
  prefix: string,
  stock: Record<string, number>,
  orders: Record<string, string>,
  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  queue: string[],
  _rejected: number,
): number {
  const id = nonNullString(event.id);
  if (id === null) return -1;

  const held = reserved[id];
  if (held !== undefined) {
    const onHand = stock[held.item] ?? 0;
    stock[held.item] = onHand + held.qty;
    delete reserved[id];
    orders[id] = "cancelled";
    advanceQueue(stock, queue, pendingWants, reserved, orders);
  } else if (orders[id] === "backordered") {
    queue.splice(queue.indexOf(id), 1);
    delete pendingWants[id];
    orders[id] = "cancelled";
  } else {
    return 1;
  }
  return 0;
}

function handleShip(
  event: Record<string, unknown>,
  prefix: string,
  stock: Record<string, number>,
  orders: Record<string, string>,
  reserved: Record<string, Want>,
  _pendingWants: Record<string, Want>,
  _queue: string[],
  _rejected: number,
): number {
  const id = nonNullString(event.id);
  if (id === null) return -1;
  const qty = event.qty;
  if (qty !== undefined && !isPosInt(qty)) return -1;

  const r = reserved[id];
  if (r === undefined) {
    return 1;
  } else if (qty === undefined || qty === r.qty) {
    delete reserved[id];
    orders[id] = "shipped";
  } else if (qty < r.qty) {
    r.qty = r.qty - qty;
    orders[id] = "partial";
  } else {
    return 1;
  }
  return 0;
}

function handleRestock(
  event: Record<string, unknown>,
  prefix: string,
  stock: Record<string, number>,
  orders: Record<string, string>,
  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  queue: string[],
  _rejected: number,
): number {
  const item = nonNullString(event.item);
  if (item === null) return -1;
  const qty = event.qty;
  if (!isPosInt(qty)) return -1;

  const onHand = stock[item] ?? 0;
  stock[item] = onHand + qty;
  advanceQueue(stock, queue, pendingWants, reserved, orders);
  return 0;
}

function handleExpire(
  event: Record<string, unknown>,
  prefix: string,
  stock: Record<string, number>,
  orders: Record<string, string>,
  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  queue: string[],
  _rejected: number,
): number {
  const id = nonNullString(event.id);
  if (id === null) return -1;

  const held = reserved[id];
  if (held !== undefined) {
    const onHand = stock[held.item] ?? 0;
    stock[held.item] = onHand + held.qty;
    delete reserved[id];
    orders[id] = "expired";
    advanceQueue(stock, queue, pendingWants, reserved, orders);
  } else {
    return 1;
  }
  return 0;
}

const HANDLERS: Record<string, EventHandler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;

  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    const val = rawStock[item];
    if (!isNonNegInt(val)) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = val;
  }

  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const orders: Record<string, string> = {};
  const reserved: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  let rejected = 0;

  for (let i = 0; i < input.events.length; i++) {
    const ev = input.events[i];
    if (typeof ev !== "object" || ev === null) {
      return { ok: false, error: `event ${i}: malformed` };
    }
    const event = ev as Record<string, unknown>;

    const tag = event.type;
    if (typeof tag !== "string") {
      return { ok: false, error: `event ${i}: bad type` };
    }

    const handler = HANDLERS[tag];
    if (handler === undefined) {
      return { ok: false, error: `event ${i}: bad type` };
    }

    const prefix = `event ${i}: `;
    const result = handler(event, prefix, stock, orders, reserved, pendingWants, queue, rejected);
    if (result === -1) {
      return { ok: false, error: prefix + "bad event" };
    }
    rejected += result;
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(
  orders: Record<string, string>,
): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

