  if (typeof raw !== "object" || raw === null) {
    return "malformed batch";
  }
  const batch = raw as Record<string, unknown>;
  if (!Array.isArray(batch.readings)) {
    return "missing readings";
  }
  const readings = batch.readings;
  if (readings.length === 0) {
    return "empty batch";
  }
  if (readings.length > MAX_READINGS) {
    return "batch too large";
  }
  return null;
}

function parseReading(entry: unknown, index: number): Reading | string {
  if (typeof entry !== "object" || entry === null) {
    return `reading ${index}: malformed`;
  }
  const record = entry as Record<string, unknown>;
  if (typeof record.channel !== "string" || record.channel.length === 0) {
    return `reading ${index}: bad channel`;
  }
  if (typeof record.value !== "number" || !Number.isInteger(record.value)) {
    return `reading ${index}: bad value`;
  }
  if (typeof record.at !== "number" || !Number.isInteger(record.at) || record.at < 0) {
    return `reading ${index}: bad timestamp`;
  }
  if (record.unit === "V") {
    return { channel: record.channel, unit: "V", value: record.value as number, at: record.at as number };
  }
  if (record.unit === "uV") {
    return { channel: record.channel, unit: "uV", value: record.value as number, at: record.at as number };
  }
  if (record.unit === "mV") {
    return { channel: record.channel, unit: "mV", value: record.value as number, at: record.at as number };
  }
  return `reading ${index}: bad unit`;
}



function normalizeValue(unit: string, value: number): number {
  switch (unit) {
    case "V": return value * 1000;
    case "uV": return Math.trunc(value / 1000);
