export function classifySignal(millivolts: number): string {
  if (millivolts >= 900) return "critical";
  if (millivolts >= 600) return "loaded";
  if (millivolts >= 200) return "active";
  if (millivolts >= 50) return "idle";
  if (millivolts >= 0) return "standby";
  return "negative";
}

function severityRank(label: string): number {
  return SEVERITY[label] ?? 0;
}

function collectAlerts(parsed: ParsedReading[], labels: string[]): string[] {
  const alerts: string[] = [];
  for (let i = 0; i < parsed.length; i++) {
    const label = labels[i];
    if (label === "critical" || label === "loaded" || label === "negative") {
      alerts.push(`${parsed[i].channel}:${label}`);
    }
  }
  return alerts;
}

function channelSummaries(parsed: ParsedReading[], labels: string[]): Record<string, ChannelSummary> {
  const channels: Record<string, ChannelSummary> = {};
  for (let i = 0; i < parsed.length; i++) {
    const reading = parsed[i];
    const label = labels[i];
    const existing = channels[reading.channel];
    if (existing === undefined) {
      channels[reading.channel] = { count: 1, min: reading.millivolts, max: reading.millivolts, worst: label };
      continue;
    }
    existing.count++;
    if (reading.millivolts < existing.min) existing.min = reading.millivolts;
    if (reading.millivolts > existing.max) existing.max = reading.millivolts;
    if (severityRank(label) > severityRank(existing.worst)) existing.worst = label;
  }
  return channels;
}

function buildReport(readingCount: number, channelCount: number, alertCount: number, labels: string[]): string {
  let worst = "standby";
  for (const label of labels) {
    if (severityRank(label) > severityRank(worst)) worst = label;
  }
  return `readings=${readingCount};channels=${channelCount};alerts=${alertCount};worst=${worst}`;
}

export interface Reading {
  channel: string;
  unit: string;
  value: number;
  at: number;
