  count: number;
  min: number;
  max: number;
  worst: string;
}

export interface BatchResult {
  ok: boolean;
  error?: string;
  readings?: number;
  labels?: string[];
  channels?: Record<string, ChannelSummary>;
  alerts?: string[];
  report?: string;
}

const MAX_READINGS = 500;
const UNITS = ["uV", "mV", "V"];

export function processBatch(raw: unknown): BatchResult {
  const batchError = validateBatch(raw);
  if (batchError !== null) {
    return { ok: false, error: batchError };
  }
  const entries = (raw as { readings: unknown[] }).readings;
  const parsed: ParsedReading[] = [];
  let index = 0;
  for (const entry of entries) {
    const outcome = parseReading(entry, index++);
    if (typeof outcome === "string") {
      return { ok: false, error: outcome };
    }
    parsed.push({
      channel: outcome.channel,
      millivolts: normalizeValue(outcome.unit, outcome.value),
      at: outcome.at,
    });
