  const worst = labels.reduce((w, l) => (severityRank(l) > severityRank(w) ? l : w), "standby");
  const alerts = collectAlerts(parsed);
  const channels = channelSummaries(parsed);
  const report = buildReport(parsed.length, Object.keys(channels).length, alerts.length, worst);
  return { ok: true, readings: parsed.length, labels, channels, alerts, report };
