interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface Env {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

type Handler = (env: Env, index: number, evt: Record<string, unknown>) => string | undefined;

function drainQueue(env: Env): void {
  for (let i = 0; i < env.queue.length; i++) {
    const pid = env.queue[i];
    const want = env.pendingWants[pid];
    if ((env.stock[want.item] ?? 0) >= want.qty) {
      env.stock[want.item] -= want.qty;
      env.reserved[pid] = { item: want.item, qty: want.qty };
      env.orders[pid] = "reserved";
      delete env.pendingWants[pid];
      env.queue.splice(i, 1);
      i--;
    }
  }
}

function processOrder(env: Env, index: number, evt: Record<string, unknown>): string | undefined {
  const id = evt.id;
  if (typeof id !== "string" || id.length === 0) return `event ${index}: bad id`;
  if (env.orders[id] !== undefined) return `event ${index}: duplicate order`;
  const item = evt.item;
  if (typeof item !== "string" || item.length === 0) return `event ${index}: bad item`;
  const qty = evt.qty;
  if (typeof qty !== "number" || !Number.isInteger(qty) || qty < 1) return `event ${index}: bad qty`;

  const available = env.stock[item] ?? 0;
  if (available >= qty) {
    env.stock[item] = available - qty;
    env.reserved[id] = { item, qty };
    env.orders[id] = "reserved";
  } else {
    env.queue.push(id);
    env.pendingWants[id] = { item, qty };
    env.orders[id] = "backordered";
  }
  return undefined;
}

function processCancel(env: Env, index: number, evt: Record<string, unknown>): string | undefined {
  const id = evt.id;
  if (typeof id !== "string" || id.length === 0) return `event ${index}: bad id`;

  const holding = env.reserved[id];
  if (holding !== undefined) {
    env.stock[holding.item] = (env.stock[holding.item] ?? 0) + holding.qty;
    delete env.reserved[id];
    env.orders[id] = "cancelled";
    drainQueue(env);
  } else if (env.orders[id] === "backordered") {
    const idx = env.queue.indexOf(id);
    if (idx !== -1) {
      env.queue.splice(idx, 1);
      delete env.pendingWants[id];
    }
    env.orders[id] = "cancelled";
  } else {
    env.rejected++;
  }
  return undefined;
}

function processShip(env: Env, index: number, evt: Record<string, unknown>): string | undefined {
  const id = evt.id;
  if (typeof id !== "string" || id.length === 0) return `event ${index}: bad id`;
  const qty = evt.qty;
  if (qty !== undefined && (typeof qty !== "number" || !Number.isInteger(qty) || qty < 1)) {
    return `event ${index}: bad qty`;
  }

  const r = env.reserved[id];
  if (r === undefined) {
    env.rejected++;
  } else if (qty === undefined) {
    delete env.reserved[id];
    env.orders[id] = "shipped";
  } else if (qty === r.qty) {
    delete env.reserved[id];
    env.orders[id] = "shipped";
  } else if (qty < r.qty) {
    r.qty -= qty;
    env.orders[id] = "partial";
  } else {
    env.rejected++;
  }
  return undefined;
}

function processRestock(env: Env, index: number, evt: Record<string, unknown>): string | undefined {
  const item = evt.item;
  if (typeof item !== "string" || item.length === 0) return `event ${index}: bad item`;
  const qty = evt.qty;
  if (typeof qty !== "number" || !Number.isInteger(qty) || qty < 1) return `event ${index}: bad qty`;

  env.stock[item] = (env.stock[item] ?? 0) + qty;
  drainQueue(env);
  return undefined;
}

function processExpire(env: Env, index: number, evt: Record<string, unknown>): string | undefined {
  const id = evt.id;
  if (typeof id !== "string" || id.length === 0) return `event ${index}: bad id`;

  const holding = env.reserved[id];
  if (holding !== undefined) {
    env.stock[holding.item] = (env.stock[holding.item] ?? 0) + holding.qty;
    delete env.reserved[id];
    env.orders[id] = "expired";
    drainQueue(env);
  } else {
    env.rejected++;
  }
  return undefined;
}

const HANDLERS: Record<string, Handler> = {
  order: processOrder,
  cancel: processCancel,
  ship: processShip,
  restock: processRestock,
  expire: processExpire,
};

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;

  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  for (const item of Object.keys(input.stock as Record<string, unknown>)) {
    const val = (input.stock as Record<string, unknown>)[item];
    if (typeof val !== "number" || !Number.isInteger(val) || val < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = val;
  }

  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const env: Env = {
    stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index];
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: `event ${index}: malformed` };
    }
    const evt = event as Record<string, unknown>;
    const handler = HANDLERS[evt.type as string];
    if (handler === undefined) {
      return { ok: false, error: `event ${index}: bad type` };
    }
    const err = handler(env, index, evt);
    if (err !== undefined) {
      return { ok: false, error: err };
    }
  }

  return {
    ok: true,
    orders: env.orders,
    stock: env.stock,
    queue: env.queue,
    rejected: env.rejected,
    report: buildReport(env.orders, env.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    const status = orders[id];
    if (status in counts) {
      counts[status]++;
    }
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}
